def create_output():
    test_input = [
        [9] * 18, [9] * 18, [9] * 18,
        [9, 9, 5, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],  # row 3
        [4, 5, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],  # row 4
        [2, 1, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],  # row 5
        [9, 9, 1, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],  # row 6
    ]

    output = [row[:] for row in test_input]

    # Group values by diagonal
    # Main diagonals: r-c constant
    # Anti-diagonals: r+c constant

    # For each non-background cell, extend along both diagonals
    # But only fill cells that are NOT already occupied by different values
    # Same value overwriting same value is OK (they're the same)

    values = [(3, 2, 5), (4, 0, 4), (4, 1, 5), (5, 0, 2), (5, 1, 1), (6, 2, 1)]

    for r0, c0, val in values:
        # Extend along main diagonal r-c = r0-c0
        # Direction (-1,+1)
        for b in range(1, 100):
            r, c = r0 - b, c0 + b
            if r < 0 or c >= 18:
                break
            # Don't overwrites different values
            if output[r][c] == 9 or output[r][c] == val:
                output[r][c] = val

        # Direction (+1,-1)
        for b in range(1, 100):
            r, c = r0 + b, c0 - b
            if r >= 7 or c < 0:
                break
            if output[r][c] == 9 or output[r][c] == val:
                output[r][c] = val

        # Extend along anti-diagonal r+c = r0+c0
        # Direction (-1,-1)
        for b in range(1, 100):
            r, c = r0 - b, c0 - b
            if r < 0 or c < 0:
                break
            if output[r][c] == 9 or output[r][c] == val:
                output[r][c] = val

        # Direction (+1,+1)
        for b in range(1, 100):
            r, c = r0 + b, c0 + b
            if r >= 7 or c >= 18:
                break
            if output[r][c] == 9 or output[r][c] == val:
                output[r][c] = val

    return output

